"""RED privacy-boundary contract tests using synthetic non-identifying values."""

from dataclasses import fields
from importlib import import_module

PrivacyValidator = import_module("clinical_ingestion.domain.privacy").PrivacyValidator


RESIDUAL_PII_PHI_CASES = (
    ("synthetic_identifier_token", "RESIDUAL_PII_PHI"),
    ("synthetic_contact_token", "RESIDUAL_PII_PHI"),
)


def test_privacy_validator_blocks_each_residual_pii_phi_finding() -> None:
    validator = PrivacyValidator()

    for residual_token, expected_code in RESIDUAL_PII_PHI_CASES:
        validation = validator.validate(residual_token)

        assert validation.passed is False
        assert validation.code == expected_code


def test_safe_technical_output_exposes_only_decision_codes_and_counts() -> None:
    safe_output = PrivacyValidator().safe_output(
        approved=False,
        codes=("RESIDUAL_PII_PHI",),
        counts={"rejected": 1},
    )

    assert {field.name for field in fields(safe_output)} == {"approved", "codes", "counts"}
    assert safe_output.codes == ("RESIDUAL_PII_PHI",)
    assert safe_output.counts == {"rejected": 1}

